parameters.jsCode:
/*
 * Builds the request for the OpenAI Chat Completions API.
 *
 * The response shape is pinned with a JSON schema (structured outputs), so the
 * model cannot answer with prose or a differently named field. Everything the
 * app and the Firestore rules require is in the schema; the limits themselves
 * are enforced again in "Validate & Normalise Recipes", because a schema can
 * describe types but not our length caps.
 */
const options = $node["Validate Request Payload"].json.body;

/* The only place the model is named. Swap it here if the account has no
   access to this one (e.g. an older gpt-4o-mini). */
const MODEL = "gpt-6-luna";

const TIME_HINTS = {
  quick: "15 to 20 minutes",
  medium: "25 to 45 minutes",
  elaborate: "50 to 75 minutes"
};

const DIET_HINTS = {
  none: "no dietary restriction",
  vegetarian: "strictly vegetarian: no meat, no fish, no gelatine",
  vegan: "strictly vegan: no meat, fish, dairy, egg, honey or gelatine",
  keto: "ketogenic: very low carbohydrate, no pasta, rice, potatoes, bread or sugar"
};

const recipeProperties = {
  title: { type: "string", description: "Dish name, at most 80 characters, no quotes" },
  description: { type: "string", description: "One sentence about the dish, at most 200 characters" },
  ingredients: {
    type: "array",
    description: "Every ingredient with an amount, e.g. '200 g pasta'. Uses the user's ingredients.",
    items: { type: "string" }
  },
  missingIngredients: {
    type: "array",
    description: "At most 3 common staples the user still has to buy, name only, no amounts",
    items: { type: "string" }
  },
  steps: {
    type: "array",
    description: "4 to 8 cooking steps in order",
    items: {
      type: "object",
      additionalProperties: false,
      required: ["instruction", "assignedTo", "isParallel"],
      properties: {
        instruction: { type: "string", description: "One step, at most 300 characters" },
        assignedTo: { type: "integer", description: "Which cook does this step, from 1 to the number of cooks" },
        isParallel: { type: "boolean", description: "True when this step runs at the same time as the previous one" }
      }
    }
  },
  difficulty: { type: "string", enum: ["easy", "medium", "hard"] },
  cookingTimeMinutes: { type: "integer" },
  servings: { type: "integer" },
  cuisineStyle: { type: "string", enum: ["german", "italian", "japanese", "indian", "gourmet", "fusion"] },
  nutrition: {
    type: "object",
    description: "Per serving, realistic for the ingredients and amounts",
    additionalProperties: false,
    required: ["caloriesPerServing", "proteinGrams", "fatGrams", "carbsGrams"],
    properties: {
      caloriesPerServing: { type: "integer" },
      proteinGrams: { type: "integer" },
      fatGrams: { type: "integer" },
      carbsGrams: { type: "integer" }
    }
  }
};

const schema = {
  type: "object",
  additionalProperties: false,
  required: ["recipes"],
  properties: {
    recipes: {
      type: "array",
      description: "Exactly three different recipes",
      items: {
        type: "object",
        additionalProperties: false,
        required: Object.keys(recipeProperties),
        properties: recipeProperties
      }
    }
  }
};

const system = [
  "You are the recipe generator of the app Code a Cuisine.",
  "You write practical home-cooking recipes in English.",
  "Rules:",
  "- Return exactly three recipes that clearly differ in preparation or flavour direction.",
  "- Every recipe has to use at least 70 percent of the ingredients the user already has, listed with amounts.",
  "- Anything else the dish needs goes into missingIngredients: never more than three common basic staples.",
  "- Keep to the requested cuisine, diet, servings and cooking time.",
  "- Spread the steps over the given number of cooks; with a single cook every step is assignedTo 1 and isParallel is false.",
  "- Steps are chronological and easy enough for a beginner: say what to do, with which ingredient, and how to tell it is done.",
  "- Use waiting times (oven, simmering, resting) for the next preparation instead of standing around.",
  "- Nutrition is per serving and has to fit the ingredients: calories must roughly match protein times 4 plus carbs times 4 plus fat times 9.",
  "- Plain text only, no markdown, no emoji."
].join("\n");

const request = {
  servings: options.servings,
  cooks: options.helpers,
  cuisineStyle: options.cuisineStyle,
  diet: options.diet,
  dietRule: DIET_HINTS[options.diet] || DIET_HINTS.none,
  cookingTime: TIME_HINTS[options.timeCategory] || TIME_HINTS.medium,
  ingredientsAtHome: options.ingredients
};

return [{
  json: {
    payload: {
      model: MODEL,
      messages: [
        { role: "system", content: system },
        { role: "user", content: JSON.stringify(request) }
      ],
      response_format: {
        type: "json_schema",
        json_schema: { name: "recipe_suggestions", strict: true, schema: schema }
      }
    }
  }
}];

/*
 * Turns the model's answer into exactly the shape the app and the Firestore
 * rules expect. The JSON schema in the request already fixes the field names
 * and types; what is left to do here is
 *   - repair what a model may still get wrong (too many steps, a cook number
 *     that does not exist, a diet slip in an ingredient line),
 *   - enforce the caps from firestore.rules, so a generated recipe can never
 *     be rejected when the app saves it to the library,
 *   - throw when the answer is unusable, which sends the run down the error
 *     output into "Generate Fallback Recipes".
 */
const options = $node["Validate Request Payload"].json.body;
const counts = $node["Parse Quota Reservation"].json;

const DIFFICULTIES = ["easy", "medium", "hard"];
const CUISINES = ["german", "italian", "japanese", "indian", "gourmet", "fusion"];

function text(value, max) {
  const cleaned = String(value == null ? "" : value).replace(/\s+/g, " ").trim();
  return cleaned.length > max ? cleaned.slice(0, max - 1).trim() + "…" : cleaned;
}

function whole(value, min, max, fallback) {
  const number = Math.round(Number(value));
  if (!Number.isFinite(number)) return fallback;
  return Math.min(max, Math.max(min, number));
}

function cook(value, position) {
  const number = Math.round(Number(value));
  const valid = Number.isFinite(number) && number >= 1 && number <= options.helpers;
  return valid ? number : (position % options.helpers) + 1;
}

function list(value, max, maxLength) {
  if (!Array.isArray(value)) return [];
  const items = [];
  for (const entry of value) {
    const line = text(entry, maxLength);
    if (line) items.push(line);
    if (items.length >= max) break;
  }
  return items;
}

const raw = $json.choices && $json.choices[0] && $json.choices[0].message
  ? $json.choices[0].message.content
  : null;
if (!raw) throw new Error("OpenAI returned no message content");

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error("OpenAI did not return valid JSON: " + error.message);
}

const candidates = Array.isArray(parsed.recipes) ? parsed.recipes : [];
if (candidates.length < 3) throw new Error("OpenAI returned " + candidates.length + " recipes instead of 3");

const recipes = candidates.slice(0, 3).map(function (recipe, index) {
  const steps = (Array.isArray(recipe.steps) ? recipe.steps : []).slice(0, 30).map(function (step, position) {
    return {
      instruction: text(step && step.instruction, 300),
      /* A cook number the user does not have is not clamped but replaced by
         the next cook in turn - clamping would push every stray step onto the
         last cook and leave the first one with nothing to do. */
      assignedTo: cook(step && step.assignedTo, position),
      isParallel: options.helpers > 1 && Boolean(step && step.isParallel)
    };
  }).filter(function (step) { return step.instruction.length > 0; });

  if (!steps.length) throw new Error("Recipe " + (index + 1) + " has no usable steps");

  const nutrition = recipe.nutrition || {};
  return {
    title: text(recipe.title, 200) || "Recipe " + (index + 1),
    description: text(recipe.description, 1000) || null,
    ingredients: list(recipe.ingredients, 50, 200),
    /* The checklist caps the extras at three basic staples; the model is told
       the same, this is the hard stop. */
    missingIngredients: list(recipe.missingIngredients, 3, 200),
    steps: steps,
    difficulty: DIFFICULTIES.indexOf(recipe.difficulty) === -1 ? "medium" : recipe.difficulty,
    cookingTimeMinutes: whole(recipe.cookingTimeMinutes, 1, 600, 30),
    /* Servings and cuisine are the user's choice, not the model's. */
    servings: options.servings,
    cuisineStyle: CUISINES.indexOf(options.cuisineStyle) === -1 ? "german" : options.cuisineStyle,
    nutrition: {
      caloriesPerServing: whole(nutrition.caloriesPerServing, 0, 5000, 0),
      proteinGrams: whole(nutrition.proteinGrams, 0, 500, 0),
      fatGrams: whole(nutrition.fatGrams, 0, 500, 0),
      carbsGrams: whole(nutrition.carbsGrams, 0, 500, 0)
    }
  };
});

for (const recipe of recipes) {
  if (!recipe.ingredients.length) throw new Error("A recipe came back without ingredients");
}

return [{
  json: {
    recipes: recipes,
    quota: {
      ipRemaining: Math.max(0, 3 - counts.ipCount),
      totalRemaining: Math.max(0, 12 - counts.totalCount)
    }
  }
}];
